/// The name of 776 sound `id`, when some client release lacks it.
pub fn sound_name_776(id: u32) -> Option<&'static str> {
    ABSENT_SOUNDS_776.binary_search_by_key(&id, |(i, _)| *i).ok().map(|i| ABSENT_SOUNDS_776[i].1)
}


