/// Sorted entry names of static registries that appear only by name in NBT.
pub fn static_names(registry: &str, proto: u32) -> Option<&'static [&'static str]> {
    Some(match (registry, proto) {
        ("minecraft:environment_attribute", 774) => ENVIRONMENT_ATTRIBUTE_SORTED_774,
        ("minecraft:environment_attribute", 775) => ENVIRONMENT_ATTRIBUTE_SORTED_775,
        ("minecraft:environment_attribute", 776) => ENVIRONMENT_ATTRIBUTE_SORTED_776,
        ("minecraft:environment_attribute", 777) => ENVIRONMENT_ATTRIBUTE_SORTED_777,
        _ => return None,
    })
}

